from lib import *
S = SS('x113')
steps = [
    step("默认配置下的响应头(明文 HTTP,所有接口要 Basic 认证)。带凭据 GET /hello:200,响应头多出 cache-control: no-cache, no-store, max-age=0, must-revalidate、expires: 0、pragma: no-cache、x-content-type-options: nosniff、x-frame-options: DENY、x-xss-protection: 0。不带凭据的 401、不存在的 /nope 的 404 也是这一组头(401 另有 www-authenticate: Basic realm=\"Realm\")。classpath 里的静态文件 /a.txt 同样被加了 no-store 一组的缓存头,静态资源默认就不缓存。但控制器自己设了 Cache-Control: max-age=60 的 /cached 保留自己的 cache-control: max-age=60,没有被覆盖,也没有 expires、pragma,其余几个安全头仍在。明文 HTTP 下没有 strict-transport-security,也没有 content-security-policy。", t=tl(S(1)), mark=lidx(S(1), 'GET /cached', 'GET /a.txt'), done=lidx(S(1), 'GET /hello(带凭据)', 'GET /hello(不带凭据)', 'GET /nope'), b=bars([['带凭据的 GET /hello 的状态码', 200, '200'], ['不带凭据的状态码', 401, '401'], ['/cached 保留的 max-age(秒)', 60, '60(没被覆盖)'], ['默认 HTTP 响应里的 strict-transport-security 个数', 0, '0']], 200, done=[0, 1], mark=[2, 3]), kv=KV([['默认加的头', 'cache-control(no-store 一组)、nosniff、X-Frame-Options: DENY、X-XSS-Protection: 0'], ['错误响应', '401、404 也带这组头'], ['静态文件', '同样被加 no-store,默认不缓存'], ['控制器自己设的 Cache-Control', '保留,不被覆盖']], ['默认加的头'])),
    step("自定义与关闭。http.headers 里配 contentSecurityPolicy(\"default-src 'self'\")、frameOptions(sameOrigin)、referrerPolicy(SAME_ORIGIN)、permissionsPolicyHeader(\"geolocation=()\"):响应头里多了 content-security-policy: default-src 'self'、permissions-policy: geolocation=()、referrer-policy: same-origin,x-frame-options 从 DENY 变成 SAMEORIGIN,其余默认头不变。默认没有 CSP、Referrer-Policy、Permissions-Policy,要自己加。headers.disable() 把这些默认头全部去掉:响应里一个安全相关的头都没有——包括 no-store 一组缓存头。", t=tl(S(2)), mark=lidx(S(2), 'headers.disable()'), done=lidx(S(2), '自定义 CSP'), b=bars([['默认配置下的 CSP / Referrer-Policy / Permissions-Policy 个数', 0, '0'], ['自定义后新增的头个数(CSP、permissions-policy、referrer-policy)', 3, '3'], ['headers.disable() 之后剩下的安全头个数', 0, '0']], 3, done=[0, 1], mark=[2]), kv=KV([['CSP、Referrer-Policy、Permissions-Policy', '默认没有,要自己配'], ['X-Frame-Options', 'DENY → SAMEORIGIN'], ['headers.disable()', '默认头全没了,包括缓存头'], ['其余默认头', '自定义时保持不变']], ['CSP、Referrer-Policy、Permissions-Policy'])),
    step("HSTS 与 HTTPS 重定向(Tomcat 开自签 TLS,再开一个 HTTP 连接器)。HTTPS 的 GET /hello 是 200,多了 strict-transport-security: max-age=31536000 ; includeSubDomains;自定义 maxAgeInSeconds(600) 加 includeSubDomains(false) 之后是 max-age=600。HSTS 只在 HTTPS 响应里出现。用 http.redirectToHttps(Customizer.withDefaults()) 加 portMapper(HTTP 端口 → HTTPS 端口):HTTP 连接器上的 GET /hello?x=1 得到 302,Location 是 https://127.0.0.1:<https 端口>/hello?x=1(路径和查询串保留);这个 302 响应本身没有任何安全头。Spring Security 6 的老写法 http.requiresChannel(c -> c.anyRequest().requiresSecure()) 在 7.0.7 里还能编译,但应用启动失败:NoClassDefFoundError: org/springframework/security/web/access/channel/ChannelEntryPoint(我查过 7.0.7 的 web 和 config 两个 jar,里面已经没有 ChannelProcessingFilter、ChannelEntryPoint 等 channel 类)。", t=tl(S(3)), mark=lidx(S(3), '[secure] HTTP(端口映射', 'requiresChannel'), done=lidx(S(3), '[secure] HTTPS GET', '[secure-hsts]'), b=bars([['HTTPS 默认 HSTS 的 max-age(秒)', 31536000, '31536000'], ['自定义后的 max-age(秒)', 600, '600'], ['HTTP 连接器上请求的状态码', 302, '302'], ['requiresChannel 老写法:应用能否启动(1=能)', 0, '启动失败']], 31536000, done=[0, 1], mark=[2, 3]), kv=KV([['HSTS', '只出现在 HTTPS 响应,默认 max-age=31536000 ; includeSubDomains'], ['redirectToHttps', 'HTTP 请求 302 到 HTTPS,路径与查询串保留,需要 portMapper'], ['requiresChannel', '7.0.7 里启动即 NoClassDefFoundError,改用 redirectToHttps'], ['302 响应本身', '不带安全头']], ['redirectToHttps'])),
    step("放在反向代理后面(Tomcat 只收明文 HTTP,代理用 X-Forwarded-Proto: https 说明外面是 HTTPS;端口映射把本端口映射到 9999)。没有配置 server.forward-headers-strategy 时,即使带了 X-Forwarded-Proto: https,/hello 还是 302 到 https://127.0.0.1:9999/hello,HSTS 也没有——后端认为这是个明文请求,放到真实代理后面会让每个请求都被重定向。配 server.forward-headers-strategy=framework:带 X-Forwarded-Proto: https 的请求变成 200,响应头里有 HSTS max-age=31536000 ; includeSubDomains;不带该头的仍然 302。配成 native 的结果相同:带头 200 并有 HSTS,不带头 302。所以代理后面既要在代理里转发这个头,又要在 Boot 里打开转发头策略。", t=tl(S(4)), mark=lidx(S(4), '[没有配置转发头策略] 带'), done=lidx(S(4), '[server.forward-headers-strategy=framework] 带', '[server.forward-headers-strategy=native] 带'), b=bars([['未配策略,带 X-Forwarded-Proto: https 的状态码', 302, '302(白白重定向)'], ['framework,带头的状态码', 200, '200'], ['native,带头的状态码', 200, '200'], ['framework,不带头的状态码', 302, '302']], 302, mark=[0], done=[1, 2]), kv=KV([['未配置策略', 'X-Forwarded-Proto 被忽略,仍 302'], ['framework / native', '带头 200 且带 HSTS,不带头 302'], ['结论', '代理要转发头,Boot 要打开转发头策略'], ['重定向目标', '来自 portMapper,与请求头无关']], ['未配置策略'])),
]
A = mkartx('x113', 113, 'Spring,Security,响应头,HSTS,HTTPS重定向,反向代理,真实验证,动画演示',
    '实测 Spring Security 7 的安全响应头与 HTTPS 重定向:默认加 nosniff、X-Frame-Options: DENY、no-store 一组缓存头,没有 CSP;HSTS 只出现在 HTTPS 响应里;redirectToHttps 配 portMapper 把 HTTP 302 到 HTTPS;requiresChannel 老写法在 7.0.7 里启动失败;放在反向代理后面不配 forward-headers-strategy 就会白白重定向。',
    'Spring Security 默认给你加了哪些响应头、漏了哪些?HSTS 什么时候才会出现?怎么把 HTTP 重定向到 HTTPS?放在 Nginx 后面为什么一直 302?这篇在 Spring Boot 4.0.8、Spring Security 7 上起真正的 TLS 和反向代理场景逐项实测。',
    [('没有 CSP', '默认响应头里没有 content-security-policy,要自己配'), ('启动失败', 'requiresChannel(...requiresSecure()) 在 Spring Security 7.0.7 里启动即 NoClassDefFoundError'), ('302', '不配 server.forward-headers-strategy,带了 X-Forwarded-Proto: https 也被重定向')],
    [('默认响应头', '<p>nosniff、X-Frame-Options: DENY、X-XSS-Protection: 0、no-store 一组缓存头;控制器自己设的 Cache-Control 不被覆盖;没有 CSP、HSTS(明文下)。</p>'),
     ('自定义与关闭', '<p>CSP、Referrer-Policy、Permissions-Policy 要自己配;headers.disable() 去掉全部默认头。</p>'),
     ('HSTS 与重定向', '<p>HSTS 只在 HTTPS 响应里;redirectToHttps 加 portMapper;requiresChannel 老写法 7.0.7 里启动失败。</p>'),
     ('反向代理', '<p>代理转发 X-Forwarded-Proto,Boot 配 forward-headers-strategy,否则一直 302。</p>')],
    steps,
    [ENV_X + '(Spring Security 7.0.7,内嵌 Tomcat)。所有接口要 Basic 认证(alice / pw);TLS 用 keytool 生成的自签 PKCS12 证书,Python 客户端不校验证书;额外的 HTTP 连接器通过 WebServerFactoryCustomizer 加;反向代理场景只用 Python 手工带 X-Forwarded-Proto,没有起真正的 Nginx;端口映射到的 9999 没有进程监听,只看 Location',
     '没有验证:真实浏览器对 HSTS、CSP 的处理;HSTS preload;CSP 的 report-only 与 nonce;Spring Security 6 的 requiresChannel 为什么在 7 里还留着方法但缺类(只查了 jar 里没有这些类);redirectToHttps 在没有 portMapper 时对非标准端口的行为;redirectToHttps 与 HSTS 在 307 / 308 重定向方面的区别;真实 Nginx / 云负载均衡;server.tomcat.remoteip.* 的细项配置;X-Forwarded-Host 与 X-Forwarded-Port'],
    '安全响应头')
